INSERT INTO `product` VALUES (1,'小米14 Ultra 白色限量版','xiao mi 1 4   U l t r a   bai se xian liang ban',2,2,6999.00,7,'<p>白色陶瓷机身，徕卡四摄，限量版</p><h2 style=\"text-align: start;\">📱 影像旗舰，记录每一刻精彩</h2><p style=\"text-align: start;\"><img src=\"http://8.163.40.255/uploads/2026-08-12/e166dd96-aba0-4f77-8eb9-0236ba73a535.jpg\" alt=\"1.jpg\" data-href=\"http://localhost:8080/uploads/2026-08-12/e166dd96-aba0-4f77-8eb9-0236ba73a535.jpg\" width=\"\" height=\"\" style=\"width: 50%;\"></p><h3 style=\"text-align: start; line-height: 1;\">📷 专业影像系统</h3><p style=\"text-align: start;\">5000 万像素超感光主摄 + 超广角 + 潜望长焦，全焦段覆盖。夜景模式再升级，暗光环境也能拍出明亮清晰的照片。</p><p style=\"text-align: start;\"><img src=\"http://8.163.40.255/uploads/2026-08-12/e6db9ffa-f097-4b4c-8a01-6b3894cbeba3.jpg\" alt=\"2.jpg\" data-href=\"http://localhost:8080/uploads/2026-08-12/e6db9ffa-f097-4b4c-8a01-6b3894cbeba3.jpg\" width=\"\" height=\"\" style=\"width: 50%;\"><img src=\"http://8.163.40.255/uploads/2026-08-12/46d7b935-b1ce-44b8-b98a-313ccdefb9f6.jpg\" alt=\"3.jpg\" data-href=\"http://localhost:8080/uploads/2026-08-12/46d7b935-b1ce-44b8-b98a-313ccdefb9f6.jpg\" width=\"\" height=\"\" style=\"width: 50%;\"><img src=\"http://8.163.40.255/uploads/2026-08-12/388c1ce6-b11b-41df-beaf-bd62f75e5fcc.jpg\" alt=\"4.jpg\" data-href=\"http://localhost:8080/uploads/2026-08-12/388c1ce6-b11b-41df-beaf-bd62f75e5fcc.jpg\" width=\"\" height=\"\" style=\"width: 50%;\"><img src=\"http://8.163.40.255/uploads/2026-08-12/8a51a2a7-b241-4b59-9412-e8858dca4673.jpg\" alt=\"5.jpg\" data-href=\"http://localhost:8080/uploads/2026-08-12/8a51a2a7-b241-4b59-9412-e8858dca4673.jpg\" width=\"\" height=\"\" style=\"width: 50%;\"></p><p style=\"text-align: start;\"><br></p><h3 style=\"text-align: start; line-height: 1;\">⚡ 性能巅峰</h3><p style=\"text-align: start;\">搭载最新旗舰芯片，安兔兔跑分突破 200 万。大型游戏满帧运行，多任务切换丝滑流畅。</p><h3 style=\"text-align: start; line-height: 1;\">🔋 超长续航</h3><p style=\"text-align: start;\">5000mAh 大电池 + 100W 超级快充，25 分钟充满。告别电量焦虑，从早到晚从容应对。</p><p style=\"text-align: start;\"><img src=\"http://8.163.40.255/uploads/2026-08-12/363fd5d8-5c13-4f20-a265-15ba7598f9f4.jpg\" alt=\"6.jpg\" data-href=\"http://localhost:8080/uploads/2026-08-12/363fd5d8-5c13-4f20-a265-15ba7598f9f4.jpg\" width=\"\" height=\"\" style=\"width: 50%;\"></p><h3 style=\"text-align: start; line-height: 1;\">🖥️ 沉浸式视觉体验</h3><p style=\"text-align: start;\"><br></p>','/uploads/2026-07-29/a37dd820-d69a-4083-a448-2c8076a695e0.png',1,'2026-05-11 17:02:05','2026-08-21 10:40:00',0,3,13),(2,'华为 Mate 60 Pro','hua wei   M a t e   6 0   P r o',2,2,6999.00,23,'<p>卫星通话，鸿蒙OS，玄武架构，超光变主摄</p><h2 style=\"text-align: start;\">📱 影像旗舰，记录每一刻精彩</h2><p style=\"text-align: start;\"><img src=\"http://localhost:63342/markdownPreview/847833148/api/v1/files/phone-hero.jpg\" alt=\"手机主图\" data-href=\"\" width=\"\" height=\"\" style=\"\"></p><h3 style=\"text-align: start; line-height: 1;\">📷 专业影像系统</h3><p style=\"text-align: start;\">5000 万像素超感光主摄 + 超广角 + 潜望长焦，全焦段覆盖。夜景模式再升级，暗光环境也能拍出明亮清晰的照片。</p><p style=\"text-align: start;\"><img src=\"http://localhost:63342/markdownPreview/847833148/api/v1/files/phone-camera.jpg\" alt=\"影像样张\" data-href=\"\" width=\"\" height=\"\" style=\"\"></p><h3 style=\"text-align: start; line-height: 1;\">⚡ 性能巅峰</h3><p style=\"text-align: start;\">搭载最新旗舰芯片，安兔兔跑分突破 200 万。大型游戏满帧运行，多任务切换丝滑流畅。</p><h3 style=\"text-align: start; line-height: 1;\">🔋 超长续航</h3><p style=\"text-align: start;\">5000mAh 大电池 + 100W 超级快充，25 分钟充满。告别电量焦虑，从早到晚从容应对。</p><p style=\"text-align: start;\"><img src=\"http://localhost:63342/markdownPreview/847833148/api/v1/files/phone-screen.jpg\" alt=\"屏幕显示效果\" data-href=\"\" width=\"\" height=\"\" style=\"\"></p><h3 style=\"text-align: start; line-height: 1;\">🖥️ 沉浸式视觉体验</h3><p style=\"text-align: start;\"><br></p>','/uploads/2026-05-17/ac3a98e5-0469-4b3c-afad-d029a5f4420a.jpg',1,'2026-05-11 17:02:05','2026-08-27 10:35:00',0,8,55),(3,'Apple iPhone 15 Pro','A p p l e   i P h o n e   1 5   P r o',2,2,7999.00,18,'<h2 style=\"text-align: center;\">Apple iPhone 15 Pro</h2><p style=\"text-align: center;\">钛金属设计，强大A17 Pro芯片，重新定义旗舰体验</p><p><br></p><p>A17 Pro芯片，钛金属边框，4800万主摄，实力全面进阶。全新Action按钮随心自定义操作，搭载USB‑C接口，兼顾创作、游戏与日常使用。多种配色可选，精致手感，性能强悍。</p><p><br></p><h3>✨核心亮点</h3><ul><li><strong>A17 Pro芯片</strong>：首款3纳米工艺iPhone芯片，图形性能大幅提升，轻松运行大型手游、4K视频剪辑</li><li><strong>航空级钛金属边框</strong>：更轻盈坚固，四种质感配色，握持手感出众</li><li><strong>4800万像素主摄系统</strong>：支持多焦距拍摄，随手拍出高清人像、风光大片</li><li><strong>全新自定义Action按钮</strong>：一键切换相机、手电筒、快捷指令等功能</li><li><strong>USB‑C高速接口</strong>：传输文件、充电一线多用，外出更加便捷</li><li><strong>超瓷晶面板</strong>：正面抗摔耐用，支持全天候显示屏</li></ul><p><br></p><h3>📱规格概览</h3><table style=\"width: 100%; table-layout: fixed; height: auto; border-width: 1px;\"><colgroup contenteditable=\"false\"><col width=\"90\"><col width=\"90\"></colgroup><tbody><tr><td colspan=\"1\" rowspan=\"1\" width=\"auto\" style=\"border-style: solid; border-color: rgb(204, 204, 204);\">处理器</td><td colspan=\"1\" rowspan=\"1\" width=\"auto\" style=\"border-style: solid; border-color: rgb(204, 204, 204);\">A17 Pro（3nm工艺）</td></tr><tr><td colspan=\"1\" rowspan=\"1\" width=\"auto\" style=\"border-style: solid; border-color: rgb(204, 204, 204);\">机身材质</td><td colspan=\"1\" rowspan=\"1\" width=\"auto\" style=\"border-style: solid; border-color: rgb(204, 204, 204);\">航空级钛金属边框</td></tr><tr><td colspan=\"1\" rowspan=\"1\" width=\"auto\" style=\"border-style: solid; border-color: rgb(204, 204, 204);\">显示屏</td><td colspan=\"1\" rowspan=\"1\" width=\"auto\" style=\"border-style: solid; border-color: rgb(204, 204, 204);\">超视网膜XDR显示屏，ProMotion自适应刷新率</td></tr><tr><td colspan=\"1\" rowspan=\"1\" width=\"auto\" style=\"border-style: solid; border-color: rgb(204, 204, 204);\">后置相机</td><td colspan=\"1\" rowspan=\"1\" width=\"auto\" style=\"border-style: solid; border-color: rgb(204, 204, 204);\">4800万像素主摄 + 1200万超广角 + 1200万长焦</td></tr><tr><td colspan=\"1\" rowspan=\"1\" width=\"auto\" style=\"border-style: solid; border-color: rgb(204, 204, 204);\">特色功能</td><td colspan=\"1\" rowspan=\"1\" width=\"auto\" style=\"border-style: solid; border-color: rgb(204, 204, 204);\">Action自定义按键、USB‑C、全天候显示、灵动岛</td></tr><tr><td colspan=\"1\" rowspan=\"1\" width=\"auto\" style=\"border-style: solid; border-color: rgb(204, 204, 204);\">配色</td><td colspan=\"1\" rowspan=\"1\" width=\"auto\" style=\"border-style: solid; border-color: rgb(204, 204, 204);\">黑色钛金属、白色钛金属、蓝色钛金属、原色钛金属</td></tr></tbody></table><p><br></p><h3>📦购买须知</h3><p>1. 本店商品发货前均经过功能检测，确保设备正常</p><p>2. 支持官方联保，享受正规售后服务</p><p>3. 收到商品请当场开箱验货，如有外观破损请及时联系客服</p><p>4. 请勿私自拆机，私自拆解将影响保修权益</p><p><br></p><p><em>温馨提示：不同内存版本价格不同，下单前可以咨询客服确认库存与版本</em></p>','/uploads/2026-05-16/79404ffc-8d49-47d2-81f6-8e4d168838fb.jpg',1,'2026-05-11 17:02:05','2026-08-24 15:15:00',0,3,3),(4,'联想拯救者 Y9000P 笔记本电脑','lian xiang zheng jiu zhe   Y 9 0 0 0 P   bi ji ben dian nao',3,2,8999.00,5,'<h2 style=\"text-align: center;\">联想拯救者 Y9000P 笔记本电脑</h2><p style=\"text-align: center;\">旗舰性能释放，电竞创作全能本</p><p><br></p><p>搭载英特尔 i9‑13900HX 处理器，搭配 RTX4060 独立显卡，强劲性能从容应对3A游戏、视频剪辑、3D渲染、程序多开等重度场景。2.5K超清电竞大屏，240Hz超高刷新率，画面流畅顺滑，告别拖影撕裂；霜刃Pro散热系统稳定控温，长时间高负载运行依旧稳定输出，电竞玩家与内容创作者优选设备。</p><p><br></p><h3>✨核心亮点</h3><ul><li><strong>i9‑13900HX 24核32线程旗舰处理器</strong>，多任务处理能力强悍</li><li><strong>RTX 4060 8G独立显卡</strong>，支持DLSS 3，游戏、创意工作双兼顾</li><li><strong>16英寸 2.5K分辨率 240Hz高刷新率电竞屏幕</strong>，色彩表现优秀</li><li><strong>霜刃Pro 散热架构</strong>，大面积VC均热板，持续稳定性能释放</li><li><strong>支持独显直连模式</strong>，大幅提升游戏帧率表现</li><li><strong>RGB背光键盘</strong>，丰富接口拓展，外接显示器、外设轻松适配</li></ul><p><br></p><h3>📋产品参数</h3><table style=\"width: 100%; table-layout: fixed; height: auto; border-width: 1px;\"><colgroup contenteditable=\"false\"><col width=\"90\"><col width=\"90\"></colgroup><tbody><tr><td colspan=\"1\" rowspan=\"1\" width=\"auto\" style=\"border-style: solid; border-color: rgb(204, 204, 204);\">处理器</td><td colspan=\"1\" rowspan=\"1\" width=\"auto\" style=\"border-style: solid; border-color: rgb(204, 204, 204);\">Intel i9-13900HX</td></tr><tr><td colspan=\"1\" rowspan=\"1\" width=\"auto\" style=\"border-style: solid; border-color: rgb(204, 204, 204);\">独立显卡</td><td colspan=\"1\" rowspan=\"1\" width=\"auto\" style=\"border-style: solid; border-color: rgb(204, 204, 204);\">NVIDIA RTX 4060 8G</td></tr><tr><td colspan=\"1\" rowspan=\"1\" width=\"auto\" style=\"border-style: solid; border-color: rgb(204, 204, 204);\">显示屏</td><td colspan=\"1\" rowspan=\"1\" width=\"auto\" style=\"border-style: solid; border-color: rgb(204, 204, 204);\">16英寸 2.5K 240Hz</td></tr><tr><td colspan=\"1\" rowspan=\"1\" width=\"auto\" style=\"border-style: solid; border-color: rgb(204, 204, 204);\">内存</td><td colspan=\"1\" rowspan=\"1\" width=\"auto\" style=\"border-style: solid; border-color: rgb(204, 204, 204);\">高速DDR5内存</td></tr><tr><td colspan=\"1\" rowspan=\"1\" width=\"auto\" style=\"border-style: solid; border-color: rgb(204, 204, 204);\">硬盘</td><td colspan=\"1\" rowspan=\"1\" width=\"auto\" style=\"border-style: solid; border-color: rgb(204, 204, 204);\">NVMe高速固态硬盘</td></tr><tr><td colspan=\"1\" rowspan=\"1\" width=\"auto\" style=\"border-style: solid; border-color: rgb(204, 204, 204);\">无线网络</td><td colspan=\"1\" rowspan=\"1\" width=\"auto\" style=\"border-style: solid; border-color: rgb(204, 204, 204);\">WiFi 6 无线网卡</td></tr></tbody></table><p><br></p><h3>📦购买须知</h3><p>1. 全新正品，支持官方查验，享受品牌全国联保服务</p><p>2. 发货前通电基础检测，确保设备无故障发出</p><p>3. 收到商品请开箱检查外观，出现破损、磕碰请第一时间联系客服</p><p>4. 请勿私自拆机改装，避免影响官方保修权益</p><p><br></p><p><em>温馨提示：不同内存、硬盘配置版本价格存在差异，下单前可咨询客服确认现货库存。</em></p>','/uploads/2026-08-08/bef034f5-d64c-4754-bc29-c68d05200e3d.jpg',1,'2026-05-11 17:02:05','2026-08-21 14:50:00',0,0,5),(5,'耐克 Air Max 90 运动鞋','nai ke   A i r   M a x   9 0   yun dong xie',5,3,129.00,95,'<h2 style=\"text-align: center;\">Air Max 90 经典复古运动鞋</h2><p>重塑90年代复古潮流，日常通勤、休闲穿搭优选</p><hr/><h3>产品亮点</h3><ul><li><strong>可视气垫：</strong>后跟Air气垫结构，行走有效缓震，减轻足部压力</li><li><strong>透气鞋面：</strong>多材质拼接鞋面，空气流通，长时间穿着不易闷脚</li><li><strong>橡胶外底：</strong>纹路橡胶大底，抓地稳固，耐磨防滑，适配多种路面</li><li><strong>百搭版型：</strong>经典黑白配色，长裤、运动裤、牛仔裤都能轻松搭配</li></ul><h3>穿搭与场景</h3><p>延续初代经典轮廓，复古线条辨识度拉满。兼顾造型感与实穿性，适合日常出行、逛街散步、轻量休闲活动。简约撞色设计，男女均可驾驭。</p><h3>选购小贴士</h3><ul><li>正常运动鞋尺码选购，脚型偏宽建议可选大半码</li><li>清洁建议软毛刷轻拭，避免长时间浸泡水洗</li><li>橡胶底避免长期接触油污、尖锐硬物，延长使用寿命</li></ul>','/uploads/2026-05-21/82f0d924-4cf7-44ad-b2e9-59fb8cfea61f.jpg',1,'2026-05-11 17:02:05','2026-08-17 15:30:00',0,4,2),(6,'罗技 MX Master 3S 鼠标','luo ji   M X   M a s t e r   3 S   shu biao',3,3,599.00,59,'<h2 style=\"text-align: center;\">MX Master 3S 无线蓝牙办公鼠标</h2><p>专业生产力工具，设计师/办公人群优选</p><p>————————————————</p><p><strong>✅ 8000DPI高精度传感器</strong><br><br>支持玻璃表面直接使用，光标移动顺滑，满足图像编辑、多文档处理需求。</p><p><strong>✅ 静音微动静音按键</strong><br><br>点击噪音大幅降低，办公室、居家工作不易打扰他人。</p><p><strong>✅ MagSpeed 电磁高速滚轮</strong><br><br>疾速滚动与段落滚动双模式，长文档、网页浏览效率更高。</p><p><strong>✅ 跨设备无缝控制</strong><br><br>蓝牙同时连接多台电脑，文件、文字跨设备一键复制粘贴。</p><p><strong>✅ 人体工学右手造型</strong><br><br>贴合手掌弧度，长时间办公有效缓解手腕疲劳。</p><p>————————————————</p><h3>适用人群</h3><p>日常文职、程序员、视频剪辑、平面设计等长时间使用电脑的用户；支持Windows、macOS系统。</p><h3>使用提示</h3><ul><li>可通过Logi Options+软件自定义侧键功能</li><li>Type-C快充，续航持久，支持边充边用</li><li>分为黑色、浅灰色双色可选</li></ul>','/uploads/2026-07-29/84494e85-4fdd-4b88-80e4-2d04103f17a0.png',1,'2026-05-11 17:02:05','2026-08-17 15:20:00',0,0,1),(7,'华为 FreeBuds Pro 3','hua wei   F r e e B u d s   P r o   3',2,2,1499.00,200,'<p><br></p><h1>• 双设备切换</h1><h2 style=\"text-align: start;\">🌟 旗舰降噪，听见纯粹</h2><p style=\"text-align: start;\"><img src=\"/uploads/2026-08-12/597819c5-02b7-4dc9-b25c-525c5c08cae9.png\" alt=\"华为 FreeBuds Pro 3.png\" data-href=\"/uploads/2026-08-12/597819c5-02b7-4dc9-b25c-525c5c08cae9.png\" width=\"\" height=\"\" style=\"width: 50%;\"></p><h3 style=\"text-align: start; line-height: 1;\">🎵 超 CD 级无损音质</h3><p style=\"text-align: start;\">搭载星闪连接技术与麒麟 A2 芯片，实现 1.5Mbps 无损传输，Hi-Res 双金标认证，还原每一个音符细节。</p><p style=\"text-align: start;\"><img src=\"http://localhost:63342/markdownPreview/433324984/api/v1/files/earbuds-unit.jpg\" alt=\"发声单元结构\" data-href=\"\" width=\"\" height=\"\" style=\"\"></p><h3 style=\"text-align: start; line-height: 1;\">🤫 智慧动态降噪 3.0</h3><p style=\"text-align: start;\">AI 自适应降噪算法，降噪深度提升 50%，抗风噪能力提升 80%。地铁、街道、办公室，随时静享片刻。</p><p style=\"text-align: start;\"><img src=\"http://localhost:8080/uploads/2026-08-12/b2250b70-2fe8-4648-bc91-27f4f3a3f54e.png\" alt=\"华为 FreeBuds Pro 3封面2.png\" data-href=\"http://localhost:8080/uploads/2026-08-12/b2250b70-2fe8-4648-bc91-27f4f3a3f54e.png\" width=\"\" height=\"\" style=\"width: 50%;\"></p><h3 style=\"text-align: start; line-height: 1;\">👂 舒适佩戴，久戴不累</h3><p style=\"text-align: start;\">单耳仅约 5.8g，新增 XS 耳塞，四款尺寸可选，贴合不同耳型。</p><h3 style=\"text-align: start; line-height: 1;\">🔋 超长续航 &amp; 全场景互联</h3>','/uploads/2026-07-29/643fd90a-df07-4b62-b9c3-0e2bfe0c65bc.png',1,'2026-05-11 20:35:46','2026-08-27 10:35:00',0,0,35),(8,'惠普电脑 暗影精灵','hui pu dian nao   an ying jing ling',3,2,7562.00,23,'<h1 style=\"text-align: center;\"></h1><h1 style=\"text-align: start;\">惠普暗影精灵游戏本｜战力拉满，驰骋游戏战场</h1><p>搭载英特尔 14 代酷睿处理器与 RTX 高性能独显，强劲算力释放，3A 大作流畅运行。高刷新率电竞大屏，画面丝滑无拖影；酷凉风暴 Pro 散热系统，高负载稳控温度。兼顾游戏娱乐、视频剪辑、3D 建模，学生、电竞玩家、创意工作者优选！</p><p><br></p><p><img src=\"http://8.163.40.255//uploads/2026-08-12/c656c26e-d7fa-4d27-9e0b-036cd9a90ac4.jpg\" alt=\"2.jpg\" data-href=\"http://localhost:8080/uploads/2026-08-12/c656c26e-d7fa-4d27-9e0b-036cd9a90ac4.jpg\" width=\"\" height=\"\" style=\"\"/><img src=\"http://8.163.40.255/uploads/2026-08-12/bd0654d5-da4a-4315-b7a4-78c0e2132e55.jpg\" alt=\"3.jpg\" data-href=\"http://localhost:8080/uploads/2026-08-12/bd0654d5-da4a-4315-b7a4-78c0e2132e55.jpg\" width=\"\" height=\"\" style=\"\"/></p><p><img src=\"http://8.163.40.255/uploads/2026-08-12/f56f55a9-2ecf-42a3-9883-23cea6f84ad8.jpg\" alt=\"26.jpg\" data-href=\"http://localhost:8080/uploads/2026-08-12/f56f55a9-2ecf-42a3-9883-23cea6f84ad8.jpg\" width=\"\" height=\"\" style=\"\"/></p><p><img src=\"http://8.163.40.255/uploads/2026-08-12/fc612225-d98d-4303-850e-68e67c722975.jpg\" alt=\"27.jpg\" data-href=\"http://localhost:8080/uploads/2026-08-12/fc612225-d98d-4303-850e-68e67c722975.jpg\" width=\"\" height=\"\" style=\"\"/></p><p><img src=\"http://8.163.40.255/uploads/2026-08-12/db45e7b5-2fbc-4be6-8693-00ccb030d5aa.jpg\" alt=\"28.jpg\" data-href=\"http://8.163.40.255/uploads/2026-08-12/db45e7b5-2fbc-4be6-8693-00ccb030d5aa.jpg\" width=\"\" height=\"\" style=\"\"/></p><p><img src=\"http://8.163.40.255/uploads/2026-08-12/e3bc9a7b-2391-45d7-a315-59b9a3bdc26a.jpg\" alt=\"29.jpg\" data-href=\"http://localhost:8080/uploads/2026-08-12/e3bc9a7b-2391-45d7-a315-59b9a3bdc26a.jpg\" width=\"\" height=\"\" style=\"\"/></p><p><img src=\"http://8.163.40.255/uploads/2026-08-12/840ef3d8-16f9-47e7-8f96-047e2fe063f4.jpg\" alt=\"30.jpg\" data-href=\"http://localhost:8080/uploads/2026-08-12/840ef3d8-16f9-47e7-8f96-047e2fe063f4.jpg\" width=\"\" height=\"\" style=\"\"/> </p><p><img src=\"http://8.163.40.255/uploads/2026-08-12/cdb1c388-a921-4e9e-bd75-252a95a3bbdf.jpg\" alt=\"31.jpg\" data-href=\"http://localhost:8080/uploads/2026-08-12/cdb1c388-a921-4e9e-bd75-252a95a3bbdf.jpg\" width=\"\" height=\"\" style=\"\"/></p><p><br></p>','/uploads/2026-05-16/423db857-b9da-4dd8-ae9d-a5c180ad87a8.jpg',1,'2026-05-13 17:38:00','2026-08-27 10:35:00',0,2,34),(9,'羽毛球','yu mao qiu',8,3,80.00,148,'<h2 style=\"text-align: center;\">训练专用羽毛球</h2><p>高耐打｜飞行平稳｜业余球馆日常训练用球</p><hr/><h3>产品核心优势</h3><ul><li><strong>飞行稳定：</strong>毛片均衡规整，击球不易飘，落点可控</li><li><strong>经久耐打：</strong>精选加厚羽毛，毛梗韧性强，降低断毛损耗</li><li><strong>击球手感佳：</strong>复合软木球头，回弹柔和，攻防体验均衡</li><li><strong>适配室内场馆：</strong>适合日常拉吊、多球训练、球友休闲对抗</li></ul><h3>产品介绍</h3><p>采用标准化工艺定型羽毛，毛面排列整齐，长时间连续击打不易抖动偏移。无论是羽毛球新手巩固基础动作，还是爱好者周末约球切磋，都能稳定发挥。整筒封装，携带存放更方便。</p><h3>使用与存放提示</h3><ul><li>干燥环境下，可提前适度熏蒸羽毛，有效提升耐打程度</li><li>远离阳光暴晒、潮湿位置存放，防止羽毛受潮变形</li><li>属于运动消耗品，不适合专业赛事持续高强度重杀</li></ul>','/uploads/2026-05-21/488894a5-fd55-4ab2-af2a-1a90cf4b9cb2.jpg',1,'2026-05-16 20:09:51','2026-08-24 17:50:00',0,2,11),(10,'球鞋','qiu xie',9,3,100.00,349,'<h2 style=\"text-align: center;\">轻便运动跑鞋</h2><p style=\"text-align: center;\">缓震透气 日常慢跑休闲运动鞋</p><p><br></p><p>这款跑鞋专为跑步运动打造，上脚轻盈无负担。鞋面透气面料，运动过程中有效疏导热气，减少闷脚感受；鞋底具备良好缓震性能，落地缓冲，减轻足部压力。简约潮流外观，色彩清新亮眼，兼顾慢跑健身、日常通勤、逛街穿搭，男女日常运动百