--
-- Table structure for table `product_comment`
--

DROP TABLE IF EXISTS `product_comment`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `product_comment` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `product_id` bigint NOT NULL COMMENT '商品ID',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `rating` tinyint NOT NULL DEFAULT '0' COMMENT '评分1-5',
  `content` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '评论内容',
  `images` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '图片URL列表，JSON数组格式',
  `status` tinyint DEFAULT '1' COMMENT '状态：0-隐藏 1-正常',
  `parent_id` bigint DEFAULT '0' COMMENT '父评论ID（0为顶级评论），用于楼中楼',
  `reply_user_id` bigint DEFAULT NULL COMMENT '被回复的用户ID',
  `reply_content` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '回复内容',
  `like_count` int DEFAULT '0' COMMENT '点赞数',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` tinyint DEFAULT '0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_product` (`product_id`) USING BTREE,
  KEY `idx_user` (`user_id`) USING BTREE,
  KEY `idx_parent` (`parent_id`) USING BTREE,
  KEY `idx_status` (`status`) USING BTREE,
  KEY `idx_create_time` (`create_time`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=88 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='商品评论表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `product_comment`
--

LOCK TABLES `product_comment` WRITE;
/*!40000 ALTER TABLE `product_comment` DISABLE KEYS */;
INSERT INTO `product_comment` VALUES (1,1,1,5,'非常好用，性价比高！',NULL,1,0,NULL,NULL,0,'2026-05-14 21:49:55','2026-05-14 21:49:55',0),(2,1,2,4,'还不错，物流很快。',NULL,1,0,NULL,NULL,0,'2026-05-14 21:49:55','2026-05-14 21:49:55',0),(3,2,1,3,'一般般，没有想象中好。',NULL,1,0,NULL,NULL,0,'2026-05-14 21:49:55','2026-05-14 21:49:55',0),(4,8,5,5,'真不错，推荐',NULL,1,0,NULL,NULL,0,'2026-05-15 18:17:36','2026-05-15 18:17:36',0),(5,11,6,5,'袜子不错',NULL,1,0,NULL,NULL,0,'2026-05-24 16:11:34','2026-05-24 16:11:34',0),(6,1,6,0,NULL,NULL,1,1,1,'好的',0,'2026-05-24 16:20:10','2026-05-24 16:20:10',0),(7,1,6,0,NULL,NULL,1,1,1,'好的',0,'2026-05-24 16:20:30','2026-05-24 16:20:30',0),(8,9,13,5,'球很耐打，飞行也不错，适合普通球友',NULL,1,0,NULL,NULL,0,'2026-05-30 17:13:31','2026-05-30 17:13:31',0),(9,2,6,0,NULL,NULL,1,3,1,'就是有点小贵',0,'2026-07-22 16:39:39','2026-07-22 16:39:39',0),(10,15,5,5,'面包很好吃',NULL,1,0,NULL,NULL,0,'2026-08-07 16:17:51','2026-08-07 16:17:51',0),(11,15,5,0,NULL,NULL,1,10,5,'真的',0,'2026-08-07 16:18:00','2026-08-07 16:18:00',0),(12,15,5,0,NULL,NULL,1,10,5,'111',0,'2026-08-07 16:18:12','2026-08-07 16:18:12',0),(13,1,18,5,'遥遥领先\n',NULL,1,0,NULL,NULL,0,'2026-08-17 11:41:51','2026-08-17 11:41:51',0),(14,24,2,5,'这个裤子真的绝了！拿到手一摸就知道是好料子，垂坠感特别棒，穿上瞬间腿长两米八。扎染的颜色也很正，跟图片完全没差别，爱了爱了！',NULL,1,0,NULL,NULL,0,'2026-08-21 11:20:38','2026-08-21 11:20:38',0),(15,24,2,5,'	穿着去打了三场全场篮球，必须给个好评！面料轻薄透气，汗湿了也不贴腿，风一吹就干了。裤长也刚好不卡膝盖，突破变向无阻碍。',NULL,1,0,NULL,NULL,0,'2026-08-21 11:21:35','2026-08-21 11:21:35',0),(16,10,2,4,'鞋子耐穿舒适',NULL,1,0,NULL,NULL,0,'2026-08-21 14:46:52','2026-08-21 14:46:52',0),(17,16,5,5,'便宜适合，爱推',NULL,1,0,NULL,NULL,0,'2026-08-24 15:50:43','2026-08-24 15:50:43',0),(18,14,5,5,'使用轻盈，下笔入神',NULL,1,0,NULL,NULL,0,'2026-08-24 15:51:29','2026-08-24 15:51:29',0),(19,13,5,5,'健康，适合全年龄',NULL,1,0,NULL,NULL,0,'2026-08-24 15:52:19','2026-08-24 15:52:19',0),(20,9,5,0,NULL,NULL,1,8,13,'我也打了，雀氏不错',0,'2026-08-24 16:07:07','2026-08-24 16:07:07',0),(21,9,5,5,'不错不错',NULL,1,0,NULL,NULL,0,'2026-08-24 16:07:24','2026-08-24 16:07:24',0),(22,1,1,5,'小米14 Ultra 拍照真的绝了！徕卡色彩太毒了，夜拍也清晰，不愧是影像旗舰。白色陶瓷手感无敌，就是有点重，但为了这影像我忍了！',NULL,1,0,NULL,NULL,0,'2026-05-20 10:30:00','2026-05-20 10:30:00',0),(23,1,5,4,'手机是好手机，性能没话说，但白色限量版太难抢了，蹲了好几天才买到。续航一天没问题，快充也快。扣一分是因为价格确实贵。',NULL,1,0,NULL,NULL,0,'2026-05-22 15:20:00','2026-05-22 15:20:00',0),(24,1,2,5,'从 iPhone 换过来的，系统很流畅，屏幕素质极高。拍照甩苹果几条街，尤其是长焦拍演唱会神器！白色真的很优雅，值这个价。',NULL,1,0,NULL,NULL,0,'2026-05-25 09:45:00','2026-05-25 09:45:00',0),(25,1,13,3,'性能确实强，但发热有点明显，打原神半小时边框烫手。系统偶尔有小 bug，希望后续更新能优化一下。总体还算满意，但不够完美。',NULL,1,0,NULL,NULL,0,'2026-06-01 14:10:00','2026-06-01 14:10:00',0),(26,2,1,5,'华为 Mate 60 Pro 不愧是国产之光！卫星通话虽说是噱头但关键时刻能救命。鸿蒙系统流畅得一匹，生态互联体验无敌。玄武架构摔过两次屏幕完好，真的硬！',NULL,1,0,NULL,NULL,0,'2026-05-18 08:30:00','2026-05-18 08:30:00',0),(27,2,6,5,'拿到手第一感觉就是做工精良，摄像头模组很有辨识度。拍照色彩还原很真实，尤其是夜景噪点控制得很好。电池也耐用，重度使用一天没问题。',NULL,1,0,NULL,NULL,0,'2026-05-20 17:00:00','2026-05-20 17:00:00',0),(28,2,13,4,'手机很好用，就是价格偏高。卫星通话功能其实用不上几次，但作为旗舰机该有的都有了。建议价格能再亲民一些，华为加油！',NULL,1,0,NULL,NULL,0,'2026-05-28 11:20:00','2026-05-28 11:20:00',0),(29,2,3,4,'用了一个月来评价：信号真的好！以前在电梯里失联，现在能刷短视频。续航也不错，拍照中规中矩。就是耳机孔取消了有点遗憾。',NULL,1,0,NULL,NULL,0,'2026-06-05 19:50:00','2026-06-05 19:50:00',0),(30,3,2,5,'iPhone 15 Pro 香爆了！A17 Pro 芯片强得离谱，玩崩铁全高特效稳 60 帧。钛合金边框手感高级又轻便，比上代轻了不少。USB-C 接口终于统一了，出门终于不用多带线。',NULL,1,0,NULL,NULL,0,'2026-05-15 12:00:00','2026-05-15 12:00:00',0),(31,3,5,5,'原色钛金属真的太好看了！拿到手那一刻就被惊艳到。灵动岛交互体验很新颖，Action 按钮设置成相机后抓拍特别快。续航也有提升，信号也比上一代强了。',NULL,1,0,NULL,NULL,0,'2026-05-19 16:30:00','2026-05-19 16:30:00',0),(32,3,13,4,'除了价格什么都好。iOS 系统确实丝滑，生态无敌。就是充电速度还是慢，跟安卓这边 100W 没法比。相机 log 模式对拍视频的人来说是福音，但我用不上。',NULL,1,0,NULL,NULL,0,'2026-05-26 09:15:00','2026-05-26 09:15:00',0),(33,4,5,5,'拯救者 Y9000P 打游戏真的爽！240Hz 屏幕太丝滑了，打 CS2 画面不撕裂不拖影。i9+4060 玩 3A 大作无压力，而且散热出乎意料的好，风扇声音也不算大。',NULL,1,0,NULL,NULL,0,'2026-05-21 21:00:00','2026-05-21 21:00:00',0),(34,4,2,5,'程序员用很满意！编译代码速度快，多开 IDE+虚拟机+几十个网页不卡顿。屏幕素质很高，看代码眼睛不累。性价比比同配置的 MacBook 高多了。',NULL,1,0,NULL,NULL,0,'2026-05-25 10:40:00','2026-05-25 10:40:00',0),(35,4,13,4,'性能释放确实猛，但续航是个大问题。不插电用两个小时左右就没了，基本就是个移动台式机。另外有点重，带出去不方便，适合固定位置使用。',NULL,1,0,NULL,NULL,0,'2026-06-02 14:55:00','2026-06-02 14:55:00',0),(36,5,13,5,'Air Max 90 经典就是经典！脚感软弹，后掌气垫踩开之后像踩在云上。黑白色百搭不挑衣服，牛仔裤工装裤都能搭。鞋型非常正，我是 AJ 党转 Nike 的，这双很满意。',NULL,1,0,NULL,NULL,0,'2026-05-16 18:20:00','2026-05-16 18:20:00',0),(37,5,6,4,'情怀鞋了。上脚很有复古感，做工比想象的好，走线工整没有溢胶。就是鞋底有点硬，需要穿几天踩开。尺码偏大半码，建议买小半码。',NULL,1,0,NULL,NULL,0,'2026-05-20 09:10:00','2026-05-20 09:10:00',0),(38,6,1,5,'MX Master 3S 是我用过最好的办公鼠标！电磁滚轮简直神器，浏览长文档嗖嗖的。静音按键在图书馆用完全不吵。人体工学设计对手腕太友好了，一天用 8 小时不酸。',NULL,1,0,NULL,NULL,0,'2026-05-17 11:30:00','2026-05-17 11:30:00',0),(39,6,5,5,'玻璃桌面直接用的体验太爽了，不用鼠标垫桌面干净很多。跨设备控制功能是生产力利器，一套键鼠控制三台电脑。就是价格确实小贵，但胜在体验好，值回票价。',NULL,1,0,NULL,NULL,0,'2026-05-23 13:45:00','2026-05-23 13:45:00',0),(40,7,3,5,'FreeBuds Pro 3 的降噪太强了！戴上去世界瞬间安静了。地铁上听歌完全不受干扰，音质也比上一代提升明显。星闪连接很稳，打游戏延迟基本感觉不到。',NULL,1,0,NULL,NULL,0,'2026-05-14 20:00:00','2026-05-14 20:00:00',0),(41,7,5,4,'音质和降噪都是第一梯队，尤其是降噪效果非常惊艳。但佩戴舒适度一般，戴久了耳朵有点涨。另外价格不便宜，可以考虑等促销入手。',NULL,1,0,NULL,NULL,0,'2026-05-19 08:45:00','2026-05-19 08:45:00',0),(42,7,6,5,'华为生态无缝衔接！手机靠近自动弹窗配对，平板耳机无缝切换，真的是用了就回不去了。音质通透，低音有力，续航也够用，出差坐飞机全程降噪很爽。',NULL,1,0,NULL,NULL,0,'2026-06-01 16:30:00','2026-06-01 16:30:00',0),(43,8,5,5,'暗影精灵很香！选的 i7+4060 配置，打永劫无间特效全开流畅 100+ 帧。键盘手感很好，背光也酷炫。双风扇散热确实给力，打一下午键盘区域温温的，不烫手。',NULL,1,0,NULL,NULL,0,'2026-05-18 22:15:00','2026-05-18 22:15:00',0),(44,8,2,4,'性能释放不错，屏幕素质也在线，高刷玩游戏爽。就是机身有点厚，便携性一般。适配器也大，带出去不方便。适合宿舍或者家里用，不适合经常带出门。',NULL,1,0,NULL,NULL,0,'2026-05-22 10:05:00','2026-05-22 10:05:00',0),(45,9,13,5,'这个羽毛球球友都夸好！飞行轨迹稳定，落点准，耐打度也 OK，一桶球能打两三次。价格也便宜，比实体店划算多了，以后就在这家回购了。',NULL,1,0,NULL,NULL,0,'2026-05-23 09:50:00','2026-05-23 09:50:00',0),(46,9,5,4,'球友推荐的，试了一下确实耐打，平时一周打两次，一桶能打半个月。就是球速稍微慢了一点，可能跟毛片有关系，但综合性价比还是很高的。',NULL,1,0,NULL,NULL,0,'2026-05-28 20:30:00','2026-05-28 20:30:00',0),(47,10,13,5,'这双跑鞋太轻了！穿上感觉跟没穿一样。鞋底很有弹性，跑起来缓震效果好，膝盖不疼。透气性也很好，跑了五公里脚也不闷热。推荐给所有跑步爱好者！',NULL,1,0,NULL,NULL,0,'2026-05-17 07:30:00','2026-05-17 07:30:00',0),(48,10,6,4,'日常通勤穿很合适，轻便透气，走路一天也不累脚。就是鞋底防滑性一般，瓷砖地面有点滑。颜色比图片稍微深一点，但也在接受范围内。',NULL,1,0,NULL,NULL,0,'2026-05-21 18:10:00','2026-05-21 18:10:00',0),(49,10,2,4,'用来平时健身房穿，轻便不累脚，深蹲硬拉也稳。透气性不错，健身两小时脚不闷。价格也实惠，性价比高，就是鞋型偏瘦，宽脚的朋友建议买大一码。',NULL,1,0,NULL,NULL,0,'2026-06-03 15:20:00','2026-06-03 15:20:00',0),(50,11,3,5,'袜子质量出乎意料的好！纯棉的，厚实柔软，穿着很舒服。价格也很便宜，买了十双够穿一季了。洗了几次也没有缩水变形，推荐大家买。',NULL,1,0,NULL,NULL,0,'2026-05-19 09:00:00','2026-05-19 09:00:00',0),(51,11,5,4,'日常通勤穿很合适，薄厚适中，透气不闷脚。就是颜色比图片偏暗一些，建议商家更新一下图片色差。整体来说性价比很高，会回购。',NULL,1,0,NULL,NULL,0,'2026-05-25 14:30:00','2026-05-25 14:30:00',0),(52,12,1,5,'这辆自行车性价比太高了！安装很简单，半个小时就装好了。骑起来很轻快，变速也顺畅，就是刹车需要稍微调一下。颜值也很高，上下班骑回头率拉满！',NULL,1,0,NULL,NULL,0,'2026-05-16 17:45:00','2026-05-16 17:45:00',0),(53,12,13,4,'车子整体不错，颜色比图片好看，组装也很简单。就是坐垫有点硬，骑久了屁股疼，建议自己换个软坐垫。这个价格还要啥自行车，值！',NULL,1,0,NULL,NULL,0,'2026-05-22 20:00:00','2026-05-22 20:00:00',0),(54,13,6,5,'鱼油吃了两个多月了，感觉精力确实好了一些，不像以前那么容易疲惫。颗粒不大很好吞，没有鱼腥味，这点很赞。给爸妈也回购了两瓶。',NULL,1,0,NULL,NULL,0,'2026-05-20 12:10:00','2026-05-20 12:10:00',0),(55,13,13,4,'给父母买的，他们说不错，这个纯度确实比药店的高。包装也很正规，有防伪码查了是正品。就是价格稍微高了一点，但一分钱一分货吧。',NULL,1,0,NULL,NULL,0,'2026-05-27 08:30:00','2026-05-27 08:30:00',0),(56,14,1,5,'这款笔非常好写！出墨均匀流畅，握着也舒服，有质感。办公桌上放一支显得很专业。准备再买几支送客户，包装好一点的话送礼也体面。',NULL,1,0,NULL,NULL,0,'2026-07-20 09:30:00','2026-07-20 09:30:00',0),(57,14,3,4,'笔不错，金属质感很高级，书写也很顺滑。就是有点重，写久了手会有点累，不过习惯了就好。墨水容量也够大，一支能写很久。',NULL,1,0,NULL,NULL,0,'2026-07-25 11:45:00','2026-07-25 11:45:00',0),(58,15,5,5,'这个面包巨好吃！软软的很香甜，早上配牛奶当早餐完美。包装也很讲究，没有压坏。下次再来买其他口味的，希望店家多出新品！',NULL,1,0,NULL,NULL,0,'2026-08-01 10:20:00','2026-08-01 10:20:00',0),(59,15,13,5,'第二次回购了，家里人都爱吃。面包真的超级软，口感很好，不会太甜。价格也比超市便宜，以后早餐就锁定这家了。物流也快，隔天就到了。',NULL,1,0,NULL,NULL,0,'2026-08-05 15:50:00','2026-08-05 15:50:00',0),(60,15,6,4,'面包松软好吃，味道不错。就是保质期短了点，建议商家更新一下保鲜包装。包装如果能再结实一点就好了，快递运输过程中有一袋被压扁了。',NULL,1,0,NULL,NULL,0,'2026-08-10 14:00:00','2026-08-10 14:00:00',0),(61,16,3,5,'这个抽纸非常好用！纸质柔软又厚实，比超市买的划算多了。湿水也不容易破，擦桌子擦手都很好用。已经推荐给同事了，准备再囤十包。',NULL,1,0,NULL,NULL,0,'2026-08-05 09:00:00','2026-08-05 09:00:00',0),(62,16,5,4,'纸巾质量不错，柔软度刚好，不像有些纸太薄。就是包装稍微简陋了一点，不过自用也无所谓了。价格实惠，会继续回购，当消耗品囤着。',NULL,1,0,NULL,NULL,0,'2026-08-08 16:20:00','2026-08-08 16:20:00',0),(63,17,2,5,'这个男士毛巾真的爱了！7A 抗菌不是吹的，用了半个月确实没有异味，之前用普通毛巾三天就臭了。面料很厚实，吸水性超强，擦完脸干爽舒爽。',NULL,1,0,NULL,NULL,0,'2026-08-06 21:30:00','2026-08-06 21:30:00',0),(64,17,13,5,'擦脸擦头发都用它，吸水很快不掉毛。洗了好几次了还是软软的，没有变硬。这个性价比真的可以，比超市几十块的强多了，推荐给兄弟们了。',NULL,1,0,NULL,NULL,0,'2026-08-10 18:10:00','2026-08-10 18:10:00',0),(65,17,5,4,'质量不错，厚度和吸水性都挺好。就是颜色选项有点少，希望能出更多配色。包装也简单了一点，但产品本身对得起这个价格。',NULL,1,0,NULL,NULL,0,'2026-08-15 11:50:00','2026-08-15 11:50:00',0),(66,24,5,5,'这个裤子真的绝了！拿到手一摸就知道是好料子，垂坠感特别棒，穿上瞬间腿长两米八。扎染的颜色也很正，跟图片完全没差别，爱了爱了！',NULL,1,0,NULL,NULL,0,'2026-08-22 15:20:00','2026-08-22 15:20:00',0),(67,24,13,5,'穿着去打了三场全场篮球，必须给个好评！面料轻薄透气，汗湿了也不贴腿，风一吹就干了。裤长也刚好不卡膝盖，突破变向无阻碍。',NULL,1,0,NULL,NULL,0,'2026-08-23 10:40:00','2026-08-23 10:40:00',0),(68,24,6,4,'设计很时髦，韩版宽松版型很显瘦。黑色扎染低调又不死板，夏天穿很凉快。就是尺码偏大，建议买小一号。物流也很快，隔天就到了。',NULL,1,0,NULL,NULL,0,'2026-08-24 09:00:00','2026-08-24 09:00:00',0),(69,1,5,0,'真的不重吗？我还在纠结白色和黑色',NULL,1,22,22,NULL,0,'2026-05-21 10:35:00','2026-05-21 10:35:00',0),(70,1,13,0,'我也买了白色，确实容易脏，但好看啊！',NULL,1,22,22,NULL,0,'2026-05-22 08:20:00','2026-05-22 08:20:00',0),(71,2,13,0,'卫星通话要什么条件才能用？',NULL,1,26,26,NULL,0,'2026-05-19 09:00:00','2026-05-19 09:00:00',0),(72,2,6,0,'回楼上：需要开通电信卫星卡，目前只有电信支持，在野外没信号的地方可以直连卫星应急。',NULL,1,26,26,NULL,0,'2026-05-19 14:20:00','2026-05-19 14:20:00',0),(73,2,3,0,'谢谢解答！那我得去办个电信卡了',NULL,1,26,26,NULL,0,'2026-05-20 11:10:00','2026-05-20 11:10:00',0),(74,3,5,0,'钛金属边框真的轻很多吗？跟不锈钢比手感差别大吗？',NULL,1,30,30,NULL,0,'2026-05-16 13:00:00','2026-05-16 13:00:00',0),(75,3,6,0,'轻了大概 20 克吧，手感差别还挺明显的，拿手里能感觉到轻了一截，而且边框质感更好了。',NULL,1,30,30,NULL,0,'2026-05-17 10:15:00','2026-05-17 10:15:00',0),(76,4,6,0,'你的配置是多少？我还在犹豫要不要上 i9 版本',NULL,1,33,33,NULL,0,'2026-05-22 08:00:00','2026-05-22 08:00:00',0),(77,4,2,0,'我买的 i7+4060，说实话够用了，i9 性能过剩还会更热，预算有限的话 i7 完全够。',NULL,1,33,33,NULL,0,'2026-05-22 19:30:00','2026-05-22 19:30:00',0),(78,7,2,0,'降噪开最大耳朵会涨吗？我比较敏感',NULL,1,40,40,NULL,0,'2026-05-15 10:30:00','2026-05-15 10:30:00',0),(79,7,3,0,'会有一点耳压感，但不会不舒服。它有自适应降噪，会根据环境自动调节强度，不用开到最大档也够用。',NULL,1,40,40,NULL,0,'2026-05-16 20:00:00','2026-05-16 20:00:00',0),(80,9,5,0,'这球适合打双打吗？耐不耐砸？',NULL,1,45,45,NULL,0,'2026-05-24 10:00:00','2026-05-24 10:00:00',0),(81,9,13,0,'双打没问题，毛片挺扎实的，我们双打一局能撑 20 多分钟。当然杀球多的话肯定消耗更快。',NULL,1,45,45,NULL,0,'2026-05-25 21:30:00','2026-05-25 21:30:00',0),(82,13,13,0,'这是软胶囊吗？好吞吗？',NULL,1,54,54,NULL,0,'2026-05-21 08:00:00','2026-05-21 08:00:00',0),(83,13,6,0,'是软胶囊，颗粒不算大，大概跟小拇指指甲盖差不多，很好吞，不会卡喉咙。',NULL,1,54,54,NULL,0,'2026-05-22 13:10:00','2026-05-22 13:10:00',0),(84,15,5,0,'保质期多久啊？想多买几包',NULL,1,58,58,NULL,0,'2026-08-02 12:30:00','2026-08-02 12:30:00',0),(85,15,13,0,'保质期 15 天，现在天气热建议少买多次，别囤太多。不过确实好吃，我一周就吃完了。',NULL,1,58,58,NULL,0,'2026-08-03 09:40:00','2026-08-03 09:40:00',0),(86,17,5,0,'真的不掉毛吗？毛巾最怕掉毛了',NULL,1,63,63,NULL,0,'2026-08-07 10:20:00','2026-08-07 10:20:00',0),(87,17,2,0,'实测真的不掉，洗了四五次了，水里没有浮毛。工艺可以的，对得起 7A 抗菌这名字。',NULL,1,63,63,NULL,0,'2026-08-08 22:00:00','2026-08-08 22:00:00',0);
