DROP TABLE IF EXISTS `product_intro_version`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `product_intro_version` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `product_id` bigint NOT NULL COMMENT '鍟嗗搧ID',
  `version_no` int NOT NULL COMMENT '鐗堟湰鍙凤紙姣忔?鎻愪氦瀹℃牳閫掑?锛',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '瀵屾枃鏈?HTML 姝ｆ枃',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0-鑽夌? 1-寰呭?鏍?2-宸查?杩?3-宸查┏鍥',
  `audit_remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '椹冲洖鍘熷洜/瀹℃牳鎰忚?',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_product_status` (`product_id`,`status`) USING BTREE,
  KEY `idx_product_version` (`product_id`,`version_no`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=27 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='鍟嗗搧浠嬬粛鐗堟湰';
/*!40101 SET character_set_client = @saved_cs_client */;

