INSERT INTO `product_intro_version` VALUES (1,7,1,'<p>&lt;h2&gt;🌟 旗舰降噪，听见纯粹&lt;/h2&gt;</p><p><br></p><p>&lt;p&gt;&lt;img src=\"/api/v1/files/earbuds-hero.jpg\" alt=\"耳机主图\" style=\"max-width:100%;border-radius:8px\"&gt;&lt;/p&gt;</p><p><br></p><p>&lt;h3&gt;🎵 超 CD 级无损音质&lt;/h3&gt;</p><p>&lt;p&gt;星闪连接 + 麒麟 A2 芯片，1.5Mbps 无损传输，Hi-Res 双金标认证。&lt;/p&gt;</p><p><br></p><p>&lt;h3&gt;🤫 智慧动态降噪 3.0&lt;/h3&gt;</p><p>&lt;p&gt;AI 自适应降噪，降噪深度提升 50%，抗风噪能力提升 80%。&lt;/p&gt;</p><p><br></p><p>&lt;p&gt;&lt;img src=\"/api/v1/files/earbuds-wearing.jpg\" alt=\"佩戴场景\" style=\"max-width:100%\"&gt;&lt;/p&gt;</p><p><br></p><p>&lt;h3&gt;🔋 续航与互联&lt;/h3&gt;</p><p>&lt;ul&gt;</p><p> &nbsp;&lt;li&gt;关闭降噪：31 小时续航&lt;/li&gt;</p><p> &nbsp;&lt;li&gt;支持无线充电&lt;/li&gt;</p><p> &nbsp;&lt;li&gt;双设备无缝切换&lt;/li&gt;</p><p>&lt;/ul&gt;</p><p><br></p><p>&lt;audio controls src=\"/api/v1/files/earbuds-demo.mp3\" style=\"width:100%\"&gt;&lt;/audio&gt;</p><p><br></p><p><br></p>',2,NULL,'2026-08-12 09:52:26','2026-08-12 09:52:26'),(2,7,0,'<p><br></p><h1>• 双设备切换</h1><h2 style=\"text-align: start;\">🌟 旗舰降噪，听见纯粹</h2><p style=\"text-align: start;\"><img src=\"/uploads/2026-08-12/597819c5-02b7-4dc9-b25c-525c5c08cae9.png\" alt=\"华为 FreeBuds Pro 3.png\" data-href=\"/uploads/2026-08-12/597819c5-02b7-4dc9-b25c-525c5c08cae9.png\" width=\"\" height=\"\" style=\"width: 50%;\"></p><h3 style=\"text-align: start; line-height: 1;\">🎵 超 CD 级无损音质</h3><p style=\"text-align: start;\">搭载星闪连接技术与麒麟 A2 芯片，实现 1.5Mbps 无损传输，Hi-Res 双金标认证，还原每一个音符细节。</p><p style=\"text-align: start;\"><img src=\"http://localhost:63342/markdownPreview/433324984/api/v1/files/earbuds-unit.jpg\" alt=\"发声单元结构\" data-href=\"\" width=\"\" height=\"\" style=\"\"></p><h3 style=\"text-align: start; line-height: 1;\">🤫 智慧动态降噪 3.0</h3><p style=\"text-align: start;\">AI 自适应降噪算法，降噪深度提升 50%，抗风噪能力提升 80%。地铁、街道、办公室，随时静享片刻。</p><p style=\"text-align: start;\"><img src=\"http://localhost:8080/uploads/2026-08-12/b2250b70-2fe8-4648-bc91-27f4f3a3f54e.png\" alt=\"华为 FreeBuds Pro 3封面2.png\" data-href=\"http://localhost:8080/uploads/2026-08-12/b2250b70-2fe8-4648-bc91-27f4f3a3f54e.png\" width=\"\" height=\"\" style=\"width: 50%;\"></p><h3 style=\"text-align: start; line-height: 1;\">👂 舒适佩戴，久戴不累</h3><p style=\"text-align: start;\">单耳仅约 5.8g，新增 XS 耳塞，四款尺寸可选，贴合不同耳型。</p><h3 style=\"text-align: start; line-height: 1;\">🔋 超长续航 &amp; 全场景互联</h3>',0,NULL,'2026-08-12 09:52:29','2026-08-12 09:52:29'),(3,7,2,'<p><br></p><h1>• 双设备切换</h1><h2 style=\"text-align: start;\">🌟 旗舰降噪，听见纯粹</h2><p style=\"text-align: start;\"><img src=\"/uploads/2026-08-12/597819c5-02b7-4dc9-b25c-525c5c08cae9.png\" alt=\"华为 FreeBuds Pro 3.png\" data-href=\"/uploads/2026-08-12/597819c5-02b7-4dc9-b25c-525c5c08cae9.png\" width=\"\" height=\"\" style=\"width: 189.09px;height: 22.93px;\"></p><h3 style=\"text-align: start; line-height: 1;\">🎵 超 CD 级无损音质</h3><p style=\"text-align: start;\">搭载星闪连接技术与麒麟 A2 芯片，实现 1.5Mbps 无损传输，Hi-Res 双金标认证，还原每一个音符细节。</p><p style=\"text-align: start;\"><img src=\"http://localhost:63342/markdownPreview/433324984/api/v1/files/earbuds-unit.jpg\" alt=\"发声单元结构\" data-href=\"\" width=\"\" height=\"\" style=\"\"></p><h3 style=\"text-align: start; line-height: 1;\">🤫 智慧动态降噪 3.0</h3><p style=\"text-align: start;\">AI 自适应降噪算法，降噪深度提升 50%，抗风噪能力提升 80%。地铁、街道、办公室，随时静享片刻。</p><p style=\"text-align: start;\"><img src=\"http://localhost:63342/markdownPreview/433324984/api/v1/files/earbuds-wearing.jpg\" alt=\"佩戴场景\" data-href=\"\" width=\"\" height=\"\" style=\"\"></p><h3 style=\"text-align: start; line-height: 1;\">👂 舒适佩戴，久戴不累</h3><p style=\"text-align: start;\">单耳仅约 5.8g，新增 XS 耳塞，四款尺寸可选，贴合不同耳型。</p><h3 style=\"text-align: start; line-height: 1;\">🔋 超长续航 &amp; 全场景互联</h3><p style=\"text-align: start;\"><br></p><h2 style=\"text-align: start;\">🌟 旗舰降噪，听见纯粹</h2><p style=\"text-align: start;\"><img src=\"http://localhost:63342/markdownPreview/433324984/api/v1/files/earbuds-hero.jpg\" alt=\"耳机主图\" data-href=\"\" width=\"\" height=\"\" style=\"\"></p><h3 style=\"text-align: start; line-height: 1;\">🎵 超 CD 级无损音质</h3><p style=\"text-align: start;\">搭载星闪连接技术与麒麟 A2 芯片，实现 1.5Mbps 无损传输，Hi-Res 双金标认证，还原每一个音符细节。</p><p style=\"text-align: start;\"><img src=\"http://localhost:63342/markdownPreview/433324984/api/v1/files/earbuds-unit.jpg\" alt=\"发声单元结构\" data-href=\"\" width=\"\" height=\"\" style=\"\"></p><h3 style=\"text-align: start; line-height: 1;\">🤫 智慧动态降噪 3.0</h3><p style=\"text-align: start;\">AI 自适应降噪算法，降噪深度提升 50%，抗风噪能力提升 80%。地铁、街道、办公室，随时静享片刻。</p><p style=\"text-align: start;\"><img src=\"http://localhost:63342/markdownPreview/433324984/api/v1/files/earbuds-wearing.jpg\" alt=\"佩戴场景\" data-href=\"\" width=\"\" height=\"\" style=\"\"></p><h3 style=\"text-align: start; line-height: 1;\">👂 舒适佩戴，久戴不累</h3><p style=\"text-align: start;\">单耳仅约 5.8g，新增 XS 耳塞，四款尺寸可选，贴合不同耳型。</p><h3 style=\"text-align: start; line-height: 1;\">🔋 超长续航 &amp; 全场景互联</h3><p style=\"text-align: start;\"><br></p>',2,NULL,'2026-08-12 10:16:23','2026-08-12 10:16:23'),(4,7,3,'<p><br></p><h1>• 双设备切换</h1><h2 style=\"text-align: start;\">🌟 旗舰降噪，听见纯粹</h2><p style=\"text-align: start;\"><img src=\"/uploads/2026-08-12/597819c5-02b7-4dc9-b25c-525c5c08cae9.png\" alt=\"华为 FreeBuds Pro 3.png\" data-href=\"/uploads/2026-08-12/597819c5-02b7-4dc9-b25c-525c5c08cae9.png\" width=\"\" height=\"\" style=\"width: 50%;\"></p><h3 style=\"text-align: start; line-height: 1;\">🎵 超 CD 级无损音质</h3><p style=\"text-align: start;\">搭载星闪连接技术与麒麟 A2 芯片，实现 1.5Mbps 无损传输，Hi-Res 双金标认证，还原每一个音符细节。</p><p style=\"text-align: start;\"><img src=\"http://localhost:63342/markdownPreview/433324984/api/v1/files/earbuds-unit.jpg\" alt=\"发声单元结构\" data-href=\"\" width=\"\" height=\"\" style=\"\"></p><h3 style=\"text-align: start; line-height: 1;\">🤫 智慧动态降噪 3.0</h3><p style=\"text-align: start;\">AI 自适应降噪算法，降噪深度提升 50%，抗风噪能力提升 80%。地铁、街道、办公室，随时静享片刻。</p><p style=\"text-align: start;\"><img src=\"http://localhost:8080/uploads/2026-08-12/b2250b70-2fe8-4648-bc91-27f4f3a3f54e.png\" alt=\"华为 FreeBuds Pro 3封面2.png\" data-href=\"http://localhost:8080/uploads/2026-08-12/b2250b70-2fe8-4648-bc91-27f4f3a3f54e.png\" width=\"\" height=\"\" style=\"width: 50%;\"></p><h3 style=\"text-align: start; line-height: 1;\">👂 舒适佩戴，久戴不累</h3><p style=\"text-align: start;\">单耳仅约 5.8g，新增 XS 耳塞，四款尺寸可选，贴合不同耳型。</p><h3 style=\"text-align: start; line-height: 1;\">🔋 超长续航 &amp; 全场景互联</h3>',2,NULL,'2026-08-12 10:25:27','2026-08-12 10:25:27'),(5,8,0,'<h1 style=\"text-align: center;\"></h1><h1 style=\"text-align: start;\">惠普暗影精灵游戏本｜战力拉满，驰骋游戏战场</h1><p>搭载英特尔 14 代酷睿处理器与 RTX 高性能独显，强劲算力释放，3A 大作流畅运行。高刷新率电竞大屏，画面丝滑无拖影；酷凉风暴 Pro 散热系统，高负载稳控温度。兼顾游戏娱乐、视频剪辑、3D 建模，学生、电竞玩家、创意工作者优选！</p><p><br></p><p><img src=\"http://localhost:8080/uploads/2026-08-12/c656c26e-d7fa-4d27-9e0b-036cd9a90ac4.jpg\" alt=\"2.jpg\" data-href=\"http://localhost:8080/uploads/2026-08-12/c656c26e-d7fa-4d27-9e0b-036cd9a90ac4.jpg\" width=\"\" height=\"\" style=\"\"/></p><p><br></p><p><img src=\"http://localhost:8080/uploads/2026-08-12/bd0654d5-da4a-4315-b7a4-78c0e2132e55.jpg\" alt=\"3.jpg\" data-href=\"http://localhost:8080/uploads/2026-08-12/bd0654d5-da4a-4315-b7a4-78c0e2132e55.jpg\" width=\"\" height=\"\" style=\"\"/></p><p><img src=\"http://localhost:8080/uploads/2026-08-12/f56f55a9-2ecf-42a3-9883-23cea6f84ad8.jpg\" alt=\"26.jpg\" data-href=\"http://localhost:8080/uploads/2026-08-12/f56f55a9-2ecf-42a3-9883-23cea6f84ad8.jpg\" width=\"\" height=\"\" style=\"\"/></p><p><img src=\"http://localhost:8080/uploads/2026-08-12/fc612225-d98d-4303-850e-68e67c722975.jpg\" alt=\"27.jpg\" data-href=\"http://localhost:8080/uploads/2026-08-12/fc612225-d98d-4303-850e-68e67c722975.jpg\" width=\"\" height=\"\" style=\"\"/></p><p><img src=\"http://localhost:8080/uploads/2026-08-12/db45e7b5-2fbc-4be6-8693-00ccb030d5aa.jpg\" alt=\"28.jpg\" data-href=\"http://localhost:8080/uploads/2026-08-12/db45e7b5-2fbc-4be6-8693-00ccb030d5aa.jpg\" width=\"\" height=\"\" style=\"\"/></p><p><img src=\"http://localhost:8080/uploads/2026-08-12/e3bc9a7b-2391-45d7-a315-59b9a3bdc26a.jpg\" alt=\"29.jpg\" data-href=\"http://localhost:8080/upl