DROP TABLE IF EXISTS `sys_notice`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_notice` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '通知ID',
  `title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '通知标题',
  `type` tinyint DEFAULT '0' COMMENT '通知类型（0=系统公告 1=活动通知 2=订单提醒）',
  `level` tinyint DEFAULT '0' COMMENT '通知等级（0=普通 1=重要 2=紧急）',
  `target_type` tinyint NOT NULL DEFAULT '1' COMMENT '目标类型（1-全体，2-指定用户）',
  `target_user_ids` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '指定用户ID，逗号分隔',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '通知内容（HTML）',
  `publisher_id` bigint DEFAULT NULL COMMENT '发布人ID（关联user表）',
  `publisher_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '发布人姓名',
  `publish_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '发布时间',
  `revoke_time` datetime DEFAULT NULL COMMENT '撤回时间',
  `status` tinyint DEFAULT '0' COMMENT '状态：0-草稿 1-已发布 2-已撤回',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `biz_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '涓氬姟绫诲瀷: new_order/order_paid/order_cancelled/new_message/reply_message',
  `biz_id` bigint DEFAULT NULL COMMENT '涓氬姟ID (璁㈠崟ID/鐣欒█ID)',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_publish_time` (`publish_time`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=291 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='系统通知表';
