/*!40000 ALTER TABLE `sys_notice` DISABLE KEYS */;
INSERT INTO `sys_notice` VALUES (1,'📢 系统通知：电商平台上线公告',0,1,1,NULL,'<h2 style=\"text-align: start;\">一、平台简介</h2><p style=\"text-align: start;\">欢迎来到 ShopSphere 电商平台！ 我们致力于为用户提供便捷、安全、高效的在线购物体验，同时为商家提供强大的店铺管理和营销工具。无论是买家还是卖家，都能在这里找到所需。</p><h2 style=\"text-align: start;\">二、已上线功能</h2><p style=\"text-align: start;\">👤 用户端 商品浏览与搜索：支持分类筛选、关键词搜索、商品详情查看。</p><p style=\"text-align: start;\">购物车：添加/删除商品、修改数量、一键结算。</p><p style=\"text-align: start;\">订单管理：下单、支付、取消订单、确认收货、查看历史订单。</p><p style=\"text-align: start;\">个人中心：资料修改、收货地址管理、我的收藏、我的通知。</p><p style=\"text-align: start;\">商家入驻申请：用户可提交申请成为商家，管理员审核通过后自动升级角色。</p><p style=\"text-align: start;\">🏪 商家端 商品管理：发布/编辑/上下架商品，支持封面图和相册图片上传。</p><p style=\"text-align: start;\">订单处理：查看订单明细、发货（填写快递单号）。</p><p style=\"text-align: start;\">统计数据：查看销售额、订单量趋势。</p><p style=\"text-align: start;\">我的入驻信息：查看审核状态及店铺资料。</p><p style=\"text-align: start;\">🔧 管理后台 用户管理：查询、冻结/解封用户（冻结后无法登录）。</p><p style=\"text-align: start;\">商品与分类管理：全平台商品审核、分类维护。</p><p style=\"text-align: start;\">订单管理：查看所有订单，处理售后（规划中）。</p><p style=\"text-align: start;\">商家入驻审核：查看申请资料，通过或拒绝，通过后自动变为商家角色。</p><p style=\"text-align: start;\">系统通知：发布通知（全体或指定用户），支持富文本内容，用户端可查看已读状态。</p><h2 style=\"text-align: start;\">三、待上线功能</h2><p style=\"text-align: start;\">🛒 优惠券系统：满减、折扣券，管理员可配置，用户结算时使用。</p><ul><li style=\"text-align: start;\">💬 商品评论与晒单：用户可评价商品，上传图片。</li></ul><ol><li style=\"text-align: start;\">📦 物流跟踪：集成快递接口，实时查询物流信息。</li></ol><p style=\"text-align: start;\">🔔 消息推送：WebSocket 实时通知订单状态变更。</p><p style=\"text-align: start;\">📊 数据大屏：实时展示平台交易额、用户活跃度等指标。</p><h2 style=\"text-align: start;\">四、欢迎使用</h2><p style=\"text-align: start;\">感谢你选择 ShopSphere！ 如果你在使用过程中遇到任何问题，或有改进建议，欢迎通过客服邮箱 support@shopsphere.com 联系我们。 祝您购物愉快，生意兴隆！</p><p style=\"text-align: start;\"><br></p><p style=\"text-align: start;\"><br></p><p style=\"text-align: start;\"><br></p><p style=\"text-align: start;\"><br></p>',1,'admin','2026-05-18 17:32:19',NULL,1,'2026-05-18 17:32:19','2026-05-18 17:33:30',NULL,NULL),(2,'新订单通知',3,0,2,'2','您有新的订单，订单号：177927785661587337b5f',0,'系统','2026-05-20 19:50:57',NULL,1,'2026-05-20 19:50:57','2026-05-20 22:21:23','new_order',22),(3,'订单取消通知',3,0,2,'2','订单 177927785661587337b5f 已被用户取消',0,'系统','2026-05-20 19:52:53',NULL,1,'2026-05-20 19:52:53','2026-05-20 22:21:26','order_cancelled',22),(4,'新订单通知',3,0,2,'2','您有新的订单，订单号：177927804713662b93d51',0,'系统','2026-05-20 19:54:07',NULL,1,'2026-05-20 19:54:07','2026-05-20 22:21:27','new_order',23),(5,'新订单通知',3,0,2,'3','您有新的订单，订单号：177927804713662b93d51',0,'系统','2026-05-20 19:54:07',NULL,1,'2026-05-20 19:54:07','2026-05-20 22:21:29','new_order',23),(6,'订单付款通知',3,0,2,'2','订单 177927804713662b93d51 已付款，请尽快发货',0,'系统','2026-05-20 19:54:13',NULL,1,'2026-05-20 19:54:13','2026-05-20 22:21:30','order_paid',23),(7,'订单付款通知',3,0,2,'3','订单 177927804713662b93d51 已付款，请尽快发货',0,'系统','2026-05-20 19:54:13',NULL,1,'2026-05-20 19:54:13','2026-05-20 22:21:32','order_paid',23),(9,'订单取消通知',3,0,2,'2','订单 1778940313220024b6ed7 已被用户取消',0,'系统','2026-05-20 22:14:20',NULL,1,'2026-05-20 22:14:20','2026-05-20 22:14:19','order_cancelled',14),(10,'订单已取消',3,0,2,'5','您的订单 1778940313220024b6ed7 已取消',0,'系统','2026-05-20 22:14:20',NULL,1,'2026-05-20 22:14:20','2026-05-20 22:14:19','order_cancelled',14),(11,'订单取消通知',3,0,2,'2','订单 1779007584705738606d5 已被用户取消',0,'系统','2026-05-20 22:14:23',NULL,1,'2026-05-20 22:14:23','2026-05-20 22:14:22','order_cancelled',15),(12,'订单取消通知',3,0,2,'3','订单 1779007584705738606d5 已被用户取消',0,'系统','2026-05-20 22:14:23',NULL,1,'2026-05-20 22:14:23','2026-05-20 22:14:22','order_cancelled',15),(13,'订单已取消',3,0,2,'5','您的订单 1779007584705738606d5 已取消',0,'系统','2026-05-20 22:14:23',NULL,1,'2026-05-20 22:14:23','2026-05-20 22:14:22','order_cancelled',15),(14,'新订单通知',3,0,2,'2','您有新的订单，订单号：17792864992082160aa7c',0,'系统','2026-05-20 22:14:59',NULL,1,'2026-05-20 22:14:59','2026-05-20 22:14:59','new_order',24),(15,'新订单通知',3,0,2,'3','您有新的订单，订单号：17792864992082160aa7c',0,'系统','2026-05-20 22:14:59',NULL,1,'2026-05-20 22:14:59','2026-05-20 22:14:59','new_order',24),(16,'订单